// src/pages/Dashboard.js
import React, { useEffect, useState } from 'react';
import { useNavigate, useNavigationType } from 'react-router-dom';
import styles from './dashboard-react.module.css';

export default function Dashboard() {
  const [explanations, setExplanations] = useState({});
  const [status, setStatus]             = useState('loading');
  const navigate                        = useNavigate();
  const navType                         = useNavigationType();
  const vizPath                         = '/visualizations/';

  useEffect(() => {
    // Wrap everything in an async function so we can use await
    const init = async () => {
      // 1) If this navigation was a browser Back (POP) and we flagged
      //    that we came from Chat, then clear both client & server session
      //    and redirect to Home.
      if (
        navType === 'POP' &&
        sessionStorage.getItem('cameFromDashboard') === 'true'
      ) {
        // clear client‑side flag
        sessionStorage.removeItem('cameFromDashboard');

        // clear server‑side Flask session
        await fetch('/api/reset', { method: 'POST' });

        // redirect to Home (replace history so Back won't come here again)
        navigate('/', { replace: true });
        return;
      }

      // 2) Otherwise, load your visualization files & explanations
      try {
        // Fetch list of files
        const filesRes = await fetch('/api/visualizations/files');
        if (!filesRes.ok) throw new Error(`Files fetch failed: ${filesRes.status}`);
        const files = await filesRes.json();

        // Fetch the explanations JSON
        const expRes = await fetch(`${vizPath}plot_explanations.json`);
        if (!expRes.ok) throw new Error(`Explanations fetch failed: ${expRes.status}`);
        const explanationsJson = await expRes.json();

        // Filter out the JSON itself and only keep image files
        const imageFiles = files.filter(
          fn => fn !== 'plot_explanations.json' && /\.(png|jpe?g|svg)$/i.test(fn)
        );

        // Build a map: filename → explanation
        const expls = imageFiles.reduce((acc, filename) => {
          acc[filename] = explanationsJson[filename] || '';
          return acc;
        }, {});

        setExplanations(expls);
        setStatus('ready');

        // Clear the client‑side flag here too so it can't trigger later
        sessionStorage.removeItem('cameFromDashboard');
      } catch (err) {
        console.error('Failed to load visualizations or explanations:', err);
        setStatus('error');
      }
    };

    init();
  }, [navigate, navType]);

  // Render states
  if (status === 'loading') {
    return <p className={styles.loading}>Loading visualizations…</p>;
  }
  if (status === 'error') {
    return <p className={styles.error}>Unable to load visualizations.</p>;
  }

  const entries = Object.entries(explanations);
  if (entries.length === 0) {
    return <p className={styles.loading}>No visualizations found.</p>;
  }

  return (
    <div className={styles.container}>
      <div className={styles.grid}>
        {entries.map(([filename, explanation]) => (
          <div key={filename} className={styles.card}>
            <img
              src={`${vizPath}${filename}`}
              alt={filename}
              className={styles.image}
            />
            <p className={styles.explanation}>{explanation}</p>
          </div>
        ))}
      </div>
      <div className={styles.nextWrapper}>
        <button
          className={styles.nextBtn}
          onClick={() => navigate('/chat')}
        >
          Go to Chat Stage
        </button>
      </div>
    </div>
  );
}
